let b = null;
try { b = $('Pedido de pautas').first().json.body; } catch (e) {}
if (!b) {
  const l = $('Criar lote automático').first().json;
  b = { lote_id: l.id, quantidade: l.quantidade, pedido: '', auto: true, auto_pecas: $('Modo automático ligado?').first().json.auto_pecas };
}
const ag = Object.fromEntries($('Ler agentes').all().map(i => [i.json.slug, i.json]));
const docs = $('Ler documentos').all().map(i => i.json).filter(d => d.titulo && d.ativo !== false);
const temas = $('Ler temas do Lab Brain').all().map(i => i.json).filter(t => t.id);
const recentes = $('Ler peças recentes').all().map(i => i.json).filter(p => p.pauta && !String(p.pauta).startsWith('[TESTE'));
const contextoLab = docs.filter(d => /quem é|marca|perfil/i.test(d.titulo)).map(d => '## ' + d.titulo + '\n\n' + d.conteudo).join('\n\n---\n\n');
const listaTemas = temas.slice(0, 150).map(t => '- [' + t.id + '] ' + t.titulo + ' — ' + String(t.resumo || '').slice(0, 220) + ' (fonte: ' + t.file_name + ')').join('\n');
return [{ json: {
  lote_id: b.lote_id, quantidade: Number(b.quantidade) || 5, pedido: b.pedido || '', auto: !!b.auto, auto_pecas: Number(b.auto_pecas) || 0,
  prompt_pauta: (ag['conteudo-pauta-quente']?.prompt || '') + (ag['conteudo-pauta-quente']?.observacoes ? '\n\n## Observações\n' + ag['conteudo-pauta-quente'].observacoes : ''),
  modelo_planejador: ag['conteudo-planejador']?.modelo || 'anthropic/claude-sonnet-5',
  prompt_planejador: (ag['conteudo-planejador']?.prompt || '') + (ag['conteudo-planejador']?.observacoes ? '\n\n## Observações\n' + ag['conteudo-planejador'].observacoes : ''),
  contexto_lab: contextoLab, temas: listaTemas || '(o mapa de temas do Lab Brain ainda está vazio)',
  recentes: recentes.slice(0, 30).map(p => '- ' + p.pauta + ' (' + p.formato + ')').join('\n') || '(nenhuma)'
} }];

