const c = Object.fromEntries($input.all().map(i => [i.json.chave, i.json.valor]));
if (String(c.auto_ativo).toLowerCase() !== 'true') return [];
return [{ json: { quantidade: Number(c.auto_pautas) || 5, auto_pecas: Number(c.auto_pecas) || 0 } }];

const ctx = $('Montar contexto').first().json;
if (!ctx.auto || !ctx.auto_pecas) return [];
const CANAIS = ['Instagram', 'LinkedIn', 'YouTube', 'Newsletter', 'Blog'];
const FORMATOS = ['Carrossel', 'Vídeo', 'Imagem', 'Reels', 'Post de texto', 'Artigo', 'E-mail'];
const sa = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const casar = (v, ops, pad) => ops.find(o => sa(v) === sa(o)) || ops.find(o => sa(v).includes(sa(o))) || pad;
const norm = (v, ops) => { const x = sa(v); return ops.find(o => x.startsWith(o)) || ops[0]; };
const proxDiaUtil = (i) => { const d = new Date(); d.setDate(d.getDate() + 2 + i); while ([0, 6].includes(d.getDay())) d.setDate(d.getDate() + 1); return d.toISOString().slice(0, 10); };
return $('Gravar pautas').all().slice(0, ctx.auto_pecas).map((i, n) => {
  const p = i.json;
  const dia = /^\d{4}-\d{2}-\d{2}/.test(p.data_sugerida) ? p.data_sugerida.slice(0, 10) : proxDiaUtil(n);
  return { json: {
    pauta_id: p.id, pauta: p.pauta, canal: casar(p.canal, CANAIS, 'Instagram'), formato: casar(p.formato, FORMATOS, 'Carrossel'),
    objetivo: norm(p.objetivo, ['autoridade', 'relacionamento', 'lead']), funil: norm(p.funil, ['topo', 'meio', 'fundo']),
    icp: p.icp || '', dor: p.dor || '', cta: p.cta || '', data_publicacao: dia + 'T10:00:00-03:00'
  } };
});

